        '[class*="filter-row"]':       { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
        '[class*="compactHeader"]':    { 'padding-top': '4px !important', 'padding-bottom': '4px !important', 'min-height': 'unset !important' },
        '[class*="compact-header"]':   { 'padding-top': '4px !important', 'padding-bottom': '4px !important', 'min-height': 'unset !important' },
        '[class*="liveboardFilter"]':  { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
        '[class*="FilterBar"]':        { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },

        // ── ag-Grid class overrides ───────────────────────────────────────
        '.ag-root':                              { 'background-color': '#1A1A1A !important', 'color': 'rgba(247,246,245,0.85) !important' },
        '.ag-root-wrapper':                      { 'background-color': '#1A1A1A !important' },
        '.ag-center-cols-container':             { 'background-color': '#1A1A1A !important' },
        '.ag-cell':                              { 'color': 'rgba(247,246,245,0.85) !important', 'border-color': '#2A2A2A !important' },
        '.ag-cell-value':                        { 'color': 'rgba(247,246,245,0.85) !important' },
        '.ag-cell-wrapper':                      { 'color': 'rgba(247,246,245,0.85) !important' },
        '.ag-group-value':                       { 'color': 'rgba(247,246,245,0.85) !important' },
        '.ag-row':                               { 'background-color': '#1A1A1A !important', 'border-color': '#2A2A2A !important' },
        '.ag-row-even':                          { 'background-color': '#1A1A1A !important' },
        '.ag-row-odd':                           { 'background-color': '#161616 !important' },
        '.ag-row:hover':                         { 'background-color': 'rgba(34,212,114,0.10) !important' },
        '.ag-header':                            { 'background-color': '#1E1E1E !important', 'border-color': '#2A2A2A !important' },
        '.ag-header-row':                        { 'background-color': '#1E1E1E !important' },
        '.ag-header-cell':                       { 'background-color': '#1E1E1E !important', 'color': 'rgba(247,246,245,0.55) !important' },
        '.ag-header-cell-label':                 { 'color': 'rgba(247,246,245,0.55) !important' },
        '.ag-header-cell-text':                  { 'color': 'rgba(247,246,245,0.55) !important' },
        '.ag-pinned-left-cols-container .ag-cell':  { 'background-color': '#1A1A1A !important', 'color': 'rgba(247,246,245,0.85) !important' },
        '.ag-pinned-right-cols-container .ag-cell': { 'background-color': '#1A1A1A !important', 'color': 'rgba(247,246,245,0.85) !important' },
        '.ag-cell a':                            { 'color': '#22D472 !important' },
        '.ag-cell-value a':                      { 'color': '#22D472 !important' },
        '.ag-group-value a':                     { 'color': '#22D472 !important' },

        // ── Table cells ───────────────────────────────────────────────────
        '[class*="tableCell"]':        { 'color': 'rgba(247,246,245,0.85) !important' },
        '[class*="table-cell"]':       { 'color': 'rgba(247,246,245,0.85) !important' },
        '[class*="headerCell"]':       { 'color': 'rgba(247,246,245,0.55) !important', 'background-color': '#1E1E1E !important' },
        '[class*="agCell"]':           { 'color': 'rgba(247,246,245,0.85) !important' },
        'td':                          { 'color': 'rgba(247,246,245,0.85) !important', 'border-color': '#2A2A2A !important' },
        'th':                          { 'color': 'rgba(247,246,245,0.55) !important', 'background-color': '#1E1E1E !important', 'border-color': '#2A2A2A !important' },

        // ── KPI / headline numbers ────────────────────────────────────────
        '[class*="headlineValue"]':    { 'color': '#F7F6F5 !important' },
        '[class*="kpiValue"]':         { 'color': '#F7F6F5 !important' },
        '[class*="numberValue"]':      { 'color': '#F7F6F5 !important' },
        '[class*="metricValue"]':      { 'color': '#F7F6F5 !important' },
        '[class*="comparisonValue"]':  { 'color': 'rgba(247,246,245,0.7) !important' },

        // ── Legend labels ─────────────────────────────────────────────────
        '[class*="legendLabel"]':      { 'color': 'rgba(247,246,245,0.75) !important' },
        '[class*="legendItem"]':       { 'color': 'rgba(247,246,245,0.75) !important' },

        // ── Tooltip ───────────────────────────────────────────────────────
        '[class*="tooltip"]':          { 'background-color': '#1E1E1E !important', 'color': '#F7F6F5 !important', 'border-color': '#2A2A2A !important' },
        '[class*="tooltipValue"]':     { 'color': '#F7F6F5 !important' },

        // ── Summary / total rows ──────────────────────────────────────────
        '[class*="summaryRow"]':       { 'background-color': '#1E1E1E !important', 'color': 'rgba(247,246,245,0.85) !important' },
        '[class*="totalRow"]':         { 'background-color': '#1E1E1E !important', 'color': '#F7F6F5 !important' },

        // ── Navy link text → pink ─────────────────────────────────────────
        'a':                           { 'color': '#22D472 !important' },
        'a:hover':                     { 'color': '#16A855 !important' },
        '[class*="link"]':             { 'color': '#22D472 !important' },
        '[class*="Link"]':             { 'color': '#22D472 !important' },
        '[class*="attributeValue"]':   { 'color': '#22D472 !important' },
        '[class*="cellLink"]':         { 'color': '#22D472 !important' },
      },
    },
  },
};

/**
 * SDK init — NoAuth assumes the user is already logged in to ThoughtSpot in the browser.
 */
export function buildThoughtSpotEmbedConfig(): EmbedConfig {
  return {
    thoughtSpotHost,
    authType: AuthType.None,
    suppressSearchEmbedBetaWarning: true,
    customizations: {
      iconSpriteUrl: DATABOT_ICON_URL,
      style: {
        customCSS: {
          variables: globalStyleVariables,
        },
      },
      content: {
        strings: {
          Spotter: 'Iris',
          'AI Highlights': 'Highlights',
          Pin: 'Pin',
        },
      },
    },
  };
}
